import { useState, useMemo } from "react";
import { useNavigate } from "react-router-dom";
import { Plus, Eye, Filter, Calendar, ChevronLeft, ChevronRight, Sparkles } from "lucide-react";
import { Card, PageHeader, Button, GradeBadge, SearchInput } from "@/components/ui";
import { useAllInspections, useAllStores } from "@/lib/data";
import { cn } from "@/lib/utils";

export default function InspectionList() {
  const navigate = useNavigate();
  const allInspections = useAllInspections();
  const allStores = useAllStores();
  // 构建 storeId → storeName 查找表，支持用户新建门店
  const storeNameMap = useMemo(
    () => new Map(allStores.map((s) => [s.id, s.name])),
    [allStores]
  );
  const [search, setSearch] = useState("");
  const [gradeFilter, setGradeFilter] = useState("all");
  const [page, setPage] = useState(1);

  const filtered = useMemo(() => {
    return allInspections.filter((insp) => {
      const storeName = storeNameMap.get(insp.storeId) || "未知门店";
      const matchSearch = !search || storeName.includes(search) || insp.id.toLowerCase().includes(search.toLowerCase());
      const matchGrade = gradeFilter === "all" || insp.grade === gradeFilter;
      return matchSearch && matchGrade;
    });
  }, [search, gradeFilter, allInspections, storeNameMap]);

  const pageSize = 8;
  const totalPages = Math.ceil(filtered.length / pageSize);
  const paged = filtered.slice((page - 1) * pageSize, page * pageSize);

  return (
    <div className="animate-fade-in">
      <PageHeader
        title="巡检管理"
        subtitle={`共 ${allInspections.length} 条巡检记录，覆盖 ${allStores.length} 家门店`}
        actions={
          <Button variant="gradient" onClick={() => navigate("/inspection/new")}>
            <Sparkles className="w-4 h-4" /> 新建巡检
            <Plus className="w-3.5 h-3.5" />
          </Button>
        }
      />

      {/* 筛选栏 */}
      <Card className="p-4 mb-5">
        <div className="flex items-center gap-4 flex-wrap">
          <div className="w-72">
            <SearchInput value={search} onChange={(v) => { setSearch(v); setPage(1); }} placeholder="搜索门店名称或巡检编号..." />
          </div>
          <div className="flex items-center gap-2">
            <Filter className="w-3.5 h-3.5 text-ink-400" />
            <span className="text-sm text-ink-500 font-medium">评级：</span>
            {[
              { key: "all", label: "全部", count: allInspections.length },
              { key: "优", label: "优" },
              { key: "良", label: "良" },
              { key: "中", label: "中" },
              { key: "差", label: "差" },
            ].map((g) => (
              <button
                key={g.key}
                onClick={() => { setGradeFilter(g.key); setPage(1); }}
                className={cn(
                  "px-3 py-1 rounded-md text-xs font-medium transition cursor-pointer border",
                  gradeFilter === g.key
                    ? "bg-gradient-to-r from-brand-900 to-brand-700 text-white border-transparent shadow-sm"
                    : "bg-white text-ink-500 border-ink-200 hover:border-brand-300 hover:text-brand-700"
                )}
              >
                {g.label}
              </button>
            ))}
          </div>
          <div className="ml-auto flex items-center gap-1.5 text-xs text-ink-500">
            <Calendar className="w-3.5 h-3.5" />
            <span>近 30 天</span>
            <span className="text-ink-300">·</span>
            <span className="font-semibold text-ink-700 tabular-nums">{filtered.length}</span>
            <span>条</span>
          </div>
        </div>
      </Card>

      {/* 表格 */}
      <Card className="overflow-hidden">
        <table className="w-full text-sm">
          <thead>
            <tr className="bg-gradient-to-r from-ink-50 to-ink-100/50 text-ink-500 text-xs">
              <th className="text-left px-5 py-3.5 font-semibold tracking-wider uppercase text-[10px]">巡检编号</th>
              <th className="text-left px-5 py-3.5 font-semibold tracking-wider uppercase text-[10px]">门店</th>
              <th className="text-left px-5 py-3.5 font-semibold tracking-wider uppercase text-[10px]">模板</th>
              <th className="text-left px-5 py-3.5 font-semibold tracking-wider uppercase text-[10px]">巡检员</th>
              <th className="text-left px-5 py-3.5 font-semibold tracking-wider uppercase text-[10px]">时间</th>
              <th className="text-center px-5 py-3.5 font-semibold tracking-wider uppercase text-[10px]">得分</th>
              <th className="text-center px-5 py-3.5 font-semibold tracking-wider uppercase text-[10px]">评级</th>
              <th className="text-center px-5 py-3.5 font-semibold tracking-wider uppercase text-[10px]">风险</th>
              <th className="text-right px-5 py-3.5 font-semibold tracking-wider uppercase text-[10px]">操作</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-ink-100/80">
            {paged.map((insp) => (
              <tr
                key={insp.id}
                className="group hover:bg-gradient-to-r hover:from-brand-50/40 hover:to-transparent cursor-pointer transition"
                onClick={() => navigate(`/inspection/${insp.id}`)}
              >
                <td className="px-5 py-3.5">
                  <span className="text-ink-600 font-mono text-xs">#{insp.id}</span>
                </td>
                <td className="px-5 py-3.5">
                  <span className="text-ink-800 font-medium">{storeNameMap.get(insp.storeId) || "未知门店"}</span>
                </td>
                <td className="px-5 py-3.5">
                  <span className="px-2 py-0.5 text-[11px] rounded-md bg-ink-100/60 text-ink-600 font-medium">{insp.templateName}</span>
                </td>
                <td className="px-5 py-3.5">
                  <div className="flex items-center gap-1.5">
                    <div className="w-5 h-5 rounded-full bg-gradient-to-br from-cyan-500 to-brand-700 text-white text-[10px] font-semibold flex items-center justify-center">
                      {insp.inspector[0]}
                    </div>
                    <span className="text-ink-600 text-xs">{insp.inspector}</span>
                  </div>
                </td>
                <td className="px-5 py-3.5 text-ink-500 text-xs tabular-nums">{insp.inspectTime.slice(0, 10)}</td>
                <td className="px-5 py-3.5 text-center">
                  <span className={cn(
                    "font-bold font-display tabular-nums",
                    insp.score >= 90 ? "text-emerald-600" :
                    insp.score >= 75 ? "text-brand-700" :
                    insp.score >= 60 ? "text-amber-600" : "text-red-500"
                  )}>
                    {insp.score}
                  </span>
                </td>
                <td className="px-5 py-3.5 text-center">
                  <GradeBadge grade={insp.grade} />
                </td>
                <td className="px-5 py-3.5 text-center">
                  {insp.riskCount > 0 ? (
                    <div className="inline-flex items-center gap-1">
                      {insp.highRiskCount > 0 && <span className="w-1.5 h-1.5 rounded-full bg-red-500" />}
                      {insp.midRiskCount > 0 && <span className="w-1.5 h-1.5 rounded-full bg-orange-500" />}
                      {insp.lowRiskCount > 0 && <span className="w-1.5 h-1.5 rounded-full bg-amber-500" />}
                      <span className="text-orange-500 font-semibold text-xs ml-0.5 tabular-nums">{insp.riskCount}</span>
                    </div>
                  ) : (
                    <span className="inline-flex items-center gap-1 text-emerald-500 text-xs font-medium">
                      <span className="w-1.5 h-1.5 rounded-full bg-emerald-500" /> 0
                    </span>
                  )}
                </td>
                <td className="px-5 py-3.5 text-right">
                  <button
                    className="inline-flex items-center gap-1 px-2.5 py-1 rounded-md text-xs text-brand-600 hover:bg-brand-50 transition cursor-pointer opacity-0 group-hover:opacity-100"
                    onClick={(e) => { e.stopPropagation(); navigate(`/inspection/${insp.id}`); }}
                  >
                    <Eye className="w-3.5 h-3.5" /> 详情
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>

        {/* 分页 */}
        {totalPages > 1 && (
          <div className="flex items-center justify-between px-5 py-3 border-t border-ink-100/80 bg-gradient-to-r from-ink-50/30 to-transparent">
            <span className="text-xs text-ink-500 tabular-nums">
              第 <span className="font-semibold text-ink-700">{page}</span> / {totalPages} 页
            </span>
            <div className="flex gap-1">
              <Button
                variant="secondary"
                size="sm"
                disabled={page === 1}
                onClick={() => setPage(page - 1)}
                icon={<ChevronLeft className="w-3.5 h-3.5" />}
              >
                上一页
              </Button>
              <Button
                variant="secondary"
                size="sm"
                disabled={page === totalPages}
                onClick={() => setPage(page + 1)}
              >
                下一页
                <ChevronRight className="w-3.5 h-3.5" />
              </Button>
            </div>
          </div>
        )}
      </Card>
    </div>
  );
}
